/* BattleQuiz - History.
 * Each entry carries both languages; `c` is the index of the correct option
 * in BOTH arrays, and `d` is the difficulty level 1-8.
 */
window.BANK = window.BANK || [];
window.BANK.push(
  { id:"his001", t:"history", d:1, c:0, en:{q:"Which large stone buildings are Egypt most famous for?",a:["The pyramids","Castles","Skyscrapers","Windmills"]}, tr:{q:"Mısır en çok hangi büyük taş yapılarıyla ünlüdür?",a:["Piramitler","Kaleler","Gökdelenler","Yel değirmenleri"]}, ex:{en:"The ancient Egyptians built huge stone pyramids as tombs to bury their pharaohs.",tr:"Eski Mısırlılar, firavunlarını gömmek için mezar olarak devasa taş piramitler inşa etti."} },
  { id:"his002", t:"history", d:1, c:0, en:{q:"What did knights long ago wear to protect themselves?",a:["Armour","Raincoats","Aprons","Scarves"]}, tr:{q:"Eski çağlarda şövalyeler korunmak için ne giyerdi?",a:["Zırh","Yağmurluk","Önlük","Atkı"]}, ex:{en:"Knights wore metal armour to shield their bodies from swords and arrows in battle.",tr:"Şövalyeler, savaşta kılıç ve oklara karşı bedenlerini korumak için metal zırh giyerdi."} },
  { id:"his003", t:"history", d:1, c:0, en:{q:"What did the earliest people mostly make their tools from?",a:["Stone","Plastic","Glass","Rubber"]}, tr:{q:"İlk insanlar aletlerini çoğunlukla hangi malzemeden yapardı?",a:["Taştan","Plastikten","Camdan","Lastikten"]}, ex:{en:"The earliest people shaped stone into sharp tools long before metals like bronze or iron were used.",tr:"İlk insanlar, bronz veya demir gibi metaller kullanılmadan çok önce taşı keskin araçlara şekillendirdi."} },
  { id:"his004", t:"history", d:1, c:0, en:{q:"Before electric lamps, what did people burn to light a room at night?",a:["Candles","Stones","Water","Sand"]}, tr:{q:"Elektrik lambaları yokken insanlar geceleri odayı aydınlatmak için ne yakardı?",a:["Mum","Taş","Su","Kum"]}, ex:{en:"Before electric lighting, people burned candles or oil lamps to see after dark.",tr:"Elektrikli aydınlatmadan önce insanlar karanlıkta görebilmek için mum veya yağ lambası yakardı."} },
  { id:"his005", t:"history", d:1, c:0, en:{q:"Before cars were invented, which animal usually pulled people's carts?",a:["Horse","Cat","Fish","Chicken"]}, tr:{q:"Otomobiller icat edilmeden önce insanların arabalarını genellikle hangi hayvan çekerdi?",a:["At","Kedi","Balık","Tavuk"]}, ex:{en:"Before engines existed, horses provided the pulling power for carts and carriages.",tr:"Motorlar icat edilmeden önce arabaları ve at arabalarını çeken güç atlardan geliyordu."} },
  { id:"his006", t:"history", d:1, c:0, en:{q:"How did the Vikings travel across the sea long ago?",a:["In wooden ships","In aeroplanes","In trains","In cars"]}, tr:{q:"Vikingler çok eskiden denizleri neyle aşardı?",a:["Ahşap gemilerle","Uçaklarla","Trenlerle","Otomobillerle"]}, ex:{en:"Vikings built sturdy wooden longships that let them sail long distances across open sea.",tr:"Vikingler, açık denizde uzun mesafeler kat edebilecekleri sağlam ahşap uzun gemiler inşa etti."} },
  { id:"his007", t:"history", d:1, c:0, en:{q:"What was the ruler of the Ottoman Empire called?",a:["Sultan","President","Mayor","Captain"]}, tr:{q:"Osmanlı Devleti'ni yöneten hükümdara ne denirdi?",a:["Padişah","Cumhurbaşkanı","Belediye başkanı","Kaptan"]}, ex:{en:"The Ottoman Empire was ruled by a sultan, a title passed down through one royal family.",tr:"Osmanlı İmparatorluğu, tek bir hanedandan babadan oğula geçen sultan unvanıyla yönetildi."} },
  { id:"his008", t:"history", d:1, c:0, en:{q:"In Türkiye, 23 April is celebrated as which special day?",a:["Children's Day","Mother's Day","New Year's Day","Teachers' Day"]}, tr:{q:"Türkiye'de 23 Nisan hangi özel gün olarak kutlanır?",a:["Çocuk Bayramı","Anneler Günü","Yılbaşı","Öğretmenler Günü"]}, ex:{en:"23 April marks the day Türkiye's first parliament opened in 1920, and is dedicated to children.",tr:"23 Nisan, Türkiye'nin ilk meclisinin 1920'de açıldığı günü anar ve çocuklara adanmıştır."} },
  { id:"his009", t:"history", d:1, c:0, en:{q:"Long ago, which bird was used to carry letters to faraway places?",a:["Pigeon","Penguin","Chicken","Owl"]}, tr:{q:"Eskiden uzak yerlere mektup taşımak için hangi kuş kullanılırdı?",a:["Güvercin","Penguen","Tavuk","Baykuş"]}, ex:{en:"Homing pigeons can find their way back over long distances, so people used them to carry written messages.",tr:"Posta güvercinleri uzun mesafelerden yollarını bulabildiği için insanlar onları yazılı mesaj taşımak için kullandı."} },
  { id:"his010", t:"history", d:1, k:"tf", v:true, en:{q:"Long ago, kings and queens wore crowns on their heads."}, tr:{q:"Eskiden krallar ve kraliçeler başlarına taç takardı."}, ex:{en:"Crowns, often made of gold and jewels, were a symbol showing a monarch's royal power.",tr:"Genellikle altın ve mücevherlerden yapılan taçlar, bir hükümdarın kraliyet gücünü gösteren bir simgeydi."} },
  { id:"his011", t:"history", d:1, k:"tf", v:false, en:{q:"Dinosaurs and the first people lived on Earth at the same time."}, tr:{q:"Dinozorlar ve ilk insanlar dünyada aynı dönemde yaşadı."}, ex:{en:"Dinosaurs died out about 66 million years ago, tens of millions of years before any humans existed.",tr:"Dinozorlar yaklaşık 66 milyon yıl önce, ilk insanlar ortaya çıkmadan on milyonlarca yıl önce yok oldu."} },
  { id:"his012", t:"history", d:1, k:"tf", v:true, en:{q:"In ancient Egypt, the ruler of the country was called a pharaoh."}, tr:{q:"Eski Mısır'da ülkenin hükümdarına firavun denirdi."}, ex:{en:"Ancient Egyptians called their ruler a pharaoh, believed to be a god-like king.",tr:"Eski Mısırlılar hükümdarlarına, tanrısal bir kral olduğuna inanılan firavun adını verirdi."} },
  { id:"his013", t:"history", d:1, k:"tf", v:false, en:{q:"In Türkiye, Republic Day is celebrated on 19 May."}, tr:{q:"Türkiye'de Cumhuriyet Bayramı 19 Mayıs'ta kutlanır."}, ex:{en:"Republic Day in Türkiye falls on 29 October; 19 May instead marks Atatürk's landing at Samsun.",tr:"Türkiye'de Cumhuriyet Bayramı 29 Ekim'dedir; 19 Mayıs ise Atatürk'ün Samsun'a çıkışını anar."} },
  { id:"his014", t:"history", d:1, k:"tf", v:true, en:{q:"The very first photographs were black and white, not colour."}, tr:{q:"İlk fotoğraflar renkli değil, siyah beyazdı."}, ex:{en:"Early cameras in the 1800s could only capture images in black and white, or shades of grey.",tr:"1800'lerdeki ilk fotoğraf makineleri yalnızca siyah beyaz veya gri tonlarda görüntü yakalayabiliyordu."} },
  { id:"his015", t:"history", d:1, k:"tf", v:false, en:{q:"The first animal that people tamed long ago was the cat."}, tr:{q:"İnsanların çok eskiden evcilleştirdiği ilk hayvan kediydi."}, ex:{en:"Dogs were tamed by humans tens of thousands of years ago, long before cats were, making them the first tamed animal.",tr:"Köpekler kediler evcilleştirilmeden on binlerce yıl önce insanlar tarafından evcilleştirilmişti, yani ilk evcilleştirilen hayvan köpekti."} },
  { id:"his016", t:"history", d:2, c:0, en:{q:"In which year was the Republic of Türkiye founded?",a:["1923","1919","1920","1938"]}, tr:{q:"Türkiye Cumhuriyeti hangi yıl kuruldu?",a:["1923","1919","1920","1938"]}, ex:{en:"The Republic of Türkiye was declared on 29 October 1923, after the War of Independence.",tr:"Türkiye Cumhuriyeti, Kurtuluş Savaşı'nın ardından 29 Ekim 1923'te ilan edildi."} },
  { id:"his017", t:"history", d:2, c:0, en:{q:"Who was the first person to walk on the Moon?",a:["Neil Armstrong","Yuri Gagarin","Buzz Aldrin","Michael Collins"]}, tr:{q:"Ay'a ilk ayak basan insan kimdir?",a:["Neil Armstrong","Yuri Gagarin","Buzz Aldrin","Michael Collins"]}, ex:{en:"Neil Armstrong stepped onto the Moon's surface in 1969 during the Apollo 11 mission.",tr:"Neil Armstrong, 1969'da Apollo 11 görevi sırasında Ay yüzeyine ilk ayak basan kişi oldu."} },
  { id:"his018", t:"history", d:2, c:0, en:{q:"Why was the Great Wall of China first built long ago?",a:["To keep attackers out","To hold back the sea","To carry water to cities","To mark a running track"]}, tr:{q:"Çin Seddi eski çağlarda ilk olarak neden yapıldı?",a:["Saldırganları uzak tutmak için","Denizi durdurmak için","Şehirlere su taşımak için","Koşu pisti belirlemek için"]}, ex:{en:"Ancient Chinese rulers built the Great Wall to block raids and invasions from the north.",tr:"Eski Çin hükümdarları, kuzeyden gelen akın ve istilaları engellemek için Çin Seddi'ni inşa etti."} },
  { id:"his019", t:"history", d:2, c:0, en:{q:"The ancient Colosseum arena is in which country?",a:["Italy","Greece","Spain","Egypt"]}, tr:{q:"Antik Kolezyum arenası hangi ülkededir?",a:["İtalya","Yunanistan","İspanya","Mısır"]}, ex:{en:"The Colosseum, built by the ancient Romans for gladiator shows, still stands in Rome, Italy.",tr:"Antik Romalılar tarafından gladyatör gösterileri için inşa edilen Kolezyum, hâlâ İtalya'nın Roma kentinde ayaktadır."} },
  { id:"his020", t:"history", d:2, c:0, en:{q:"Which people long ago sailed from northern Europe in long wooden ships?",a:["The Vikings","The Aztecs","The Romans","The Egyptians"]}, tr:{q:"Eski çağlarda Kuzey Avrupa'dan uzun ahşap gemilerle denize açılan halk hangisidir?",a:["Vikingler","Aztekler","Romalılar","Mısırlılar"]}, ex:{en:"Vikings from Scandinavia sailed out in longships to raid, trade and settle across Europe.",tr:"İskandinavya'dan gelen Vikingler, Avrupa'da akın düzenlemek, ticaret yapmak ve yerleşmek için uzun gemilerle denize açıldı."} },
  { id:"his021", t:"history", d:2, c:0, en:{q:"Who sailed west across the Atlantic in 1492 and reached the Americas?",a:["Christopher Columbus","Marco Polo","Captain Cook","Ferdinand Magellan"]}, tr:{q:"1492'de Atlas Okyanusu'nu batıya geçip Amerika'ya ulaşan denizci kimdir?",a:["Kristof Kolomb","Marco Polo","Kaptan Cook","Macellan"]}, ex:{en:"Columbus set sail in 1492 hoping to reach Asia, and instead landed in the Caribbean.",tr:"Kolomb, 1492'de Asya'ya ulaşmayı umarak yola çıktı ve bunun yerine Karayipler'e ulaştı."} },
  { id:"his022", t:"history", d:2, c:0, en:{q:"In the famous legend of Troy, soldiers hid inside a giant wooden model of which animal?",a:["A horse","An elephant","A bull","A bird"]}, tr:{q:"Ünlü Truva efsanesinde askerler hangi hayvanın dev tahta heykeline saklandı?",a:["At","Fil","Boğa","Kuş"]}, ex:{en:"In the legend, Greek soldiers hid inside a giant wooden horse to sneak into the city of Troy.",tr:"Efsaneye göre Yunan askerleri, Truva kentine gizlice girebilmek için dev bir tahta atın içine saklandı."} },
  { id:"his023", t:"history", d:2, c:0, en:{q:"What did the Wright brothers fly for the first time in 1903?",a:["An aeroplane","A helicopter","A hot-air balloon","A rocket"]}, tr:{q:"Wright kardeşler 1903'te ilk kez neyi uçurdu?",a:["Uçak","Helikopter","Sıcak hava balonu","Roket"]}, ex:{en:"In 1903 the Wright brothers flew the first powered aeroplane at Kitty Hawk, North Carolina.",tr:"Wright kardeşler 1903'te Kuzey Carolina'daki Kitty Hawk'ta ilk motorlu uçağı uçurdu."} },
  { id:"his024", t:"history", d:2, c:0, en:{q:"What powered the first railway locomotives in the 1800s?",a:["Steam","Petrol","Sunlight","Batteries"]}, tr:{q:"1800'lerde ilk tren lokomotiflerini hareket ettiren güç neydi?",a:["Buhar","Benzin","Güneş ışığı","Piller"]}, ex:{en:"Early locomotives burned coal to heat water into steam, which pushed pistons to turn the wheels.",tr:"İlk lokomotifler, tekerlekleri döndüren pistonları iten buharı elde etmek için kömürle suyu ısıtırdı."} },
  { id:"his025", t:"history", d:2, c:0, en:{q:"Long before writing was invented, where did people paint pictures of animals?",a:["On cave walls","In paper books","On glass windows","On metal cans"]}, tr:{q:"Yazı icat edilmeden çok önce insanlar hayvan resimlerini nereye çizerdi?",a:["Mağara duvarlarına","Kâğıt kitaplara","Cam pencerelere","Metal kutulara"]}, ex:{en:"Prehistoric people painted animals on cave walls thousands of years before writing was invented.",tr:"Tarih öncesi insanlar, yazı icat edilmeden binlerce yıl önce mağara duvarlarına hayvan resimleri çizdi."} },
  { id:"his026", t:"history", d:2, c:0, en:{q:"What do we call a scientist who digs up old objects to learn about the past?",a:["An archaeologist","An astronaut","A dentist","A weather forecaster"]}, tr:{q:"Geçmişi öğrenmek için eski eşyaları kazarak çıkaran bilim insanına ne denir?",a:["Arkeolog","Astronot","Diş hekimi","Meteorolog"]}, ex:{en:"Archaeologists dig up ancient objects and ruins to piece together how people lived long ago.",tr:"Arkeologlar, insanların geçmişte nasıl yaşadığını anlamak için eski nesneleri ve kalıntıları toprağın altından çıkarır."} },
  { id:"his027", t:"history", d:2, c:0, en:{q:"Before the printing press was invented, how were most books made?",a:["Copied out by hand","Printed in factories","Typed on computers","Made by robots"]}, tr:{q:"Matbaa icat edilmeden önce kitapların çoğu nasıl çoğaltılırdı?",a:["Elle kopyalanarak","Fabrikalarda basılarak","Bilgisayarda yazılarak","Robotlarla üretilerek"]}, ex:{en:"Before printing, monks and scribes copied every book out by hand, which took a very long time.",tr:"Matbaadan önce rahipler ve yazıcılar her kitabı elle kopyalar, bu da çok uzun zaman alırdı."} },
  { id:"his028", t:"history", d:2, c:0, en:{q:"What job made Florence Nightingale famous?",a:["Nurse","Pilot","Painter","Singer"]}, tr:{q:"Florence Nightingale hangi mesleğiyle ünlü olmuştur?",a:["Hemşire","Pilot","Ressam","Şarkıcı"]}, ex:{en:"Florence Nightingale improved care for wounded soldiers as a nurse during the Crimean War.",tr:"Florence Nightingale, Kırım Savaşı sırasında hemşire olarak yaralı askerlerin bakımını iyileştirdi."} },
  { id:"his029", t:"history", d:2, c:0, en:{q:"Hagia Sophia, built about 1500 years ago, stands in which city?",a:["Istanbul","Ankara","Athens","Cairo"]}, tr:{q:"Yaklaşık 1500 yıl önce inşa edilen Ayasofya hangi şehirdedir?",a:["İstanbul","Ankara","Atina","Kahire"]}, ex:{en:"Hagia Sophia was built in the 500s AD as a church, later a mosque, in what is now Istanbul.",tr:"Ayasofya, 500'lü yıllarda kilise olarak, sonra da cami olarak bugünkü İstanbul'da inşa edildi."} },
  { id:"his030", t:"history", d:2, k:"tf", v:true, en:{q:"The first Olympic Games were held in ancient Greece."}, tr:{q:"İlk Olimpiyat Oyunları Antik Yunanistan'da düzenlenmiştir."}, ex:{en:"The first recorded Olympic Games were held in Olympia, ancient Greece, in 776 BC.",tr:"Kayıtlara geçen ilk Olimpiyat Oyunları, MÖ 776'da antik Yunanistan'ın Olympia kentinde düzenlendi."} },
  { id:"his031", t:"history", d:2, k:"tf", v:false, en:{q:"The kings of ancient Egypt were called emperors."}, tr:{q:"Eski Mısır'ın krallarına imparator denirdi."}, ex:{en:"Ancient Egypt's rulers were called pharaohs, not emperors, a title used elsewhere like Rome.",tr:"Eski Mısır'ın hükümdarlarına imparator değil, firavun denirdi; imparator unvanı Roma gibi başka yerlerde kullanılırdı."} },
  { id:"his032", t:"history", d:2, k:"tf", v:true, en:{q:"The ancient Romans spoke Latin."}, tr:{q:"Eski Romalılar Latince konuşurdu."}, ex:{en:"Latin was the everyday language of ancient Rome and later spread across the empire.",tr:"Latince, antik Roma'nın günlük diliydi ve daha sonra imparatorluk boyunca yayıldı."} },
  { id:"his033", t:"history", d:2, k:"tf", v:true, en:{q:"The Ottoman Empire lasted for more than 600 years."}, tr:{q:"Osmanlı Devleti 600 yıldan uzun süre ayakta kaldı."}, ex:{en:"The Ottoman Empire lasted from 1299 to 1922, over 600 years of rule.",tr:"Osmanlı İmparatorluğu 1299'dan 1922'ye kadar, 600 yılı aşkın süre hüküm sürdü."} },
  { id:"his034", t:"history", d:2, k:"tf", v:false, en:{q:"Paper money was invented before metal coins."}, tr:{q:"Kâğıt para, madeni paralardan önce icat edilmiştir."}, ex:{en:"Metal coins appeared centuries before paper money, which China introduced around the 7th to 11th century AD.",tr:"Metal paralar, Çin'in 7. ile 11. yüzyıllar arasında tanıttığı kâğıt paradan yüzyıllar önce ortaya çıktı."} },
  { id:"his035", t:"history", d:3, c:0, en:{q:"Which sultan conquered Istanbul in 1453?",a:["Mehmed the Conqueror","Selim I","Suleiman the Magnificent","Bayezid II"]}, tr:{q:"1453'te İstanbul'u fetheden padişah kimdir?",a:["Fatih Sultan Mehmet","Yavuz Sultan Selim","Kanuni Sultan Süleyman","II. Bayezid"]}, ex:{en:"Mehmed the Conqueror captured Constantinople from the Byzantines in 1453, ending the Byzantine Empire.",tr:"Fatih Sultan Mehmet, 1453'te Bizans'tan Konstantinopolis'i alarak Bizans İmparatorluğu'nu sona erdirdi."} },
  { id:"his036", t:"history", d:3, c:0, en:{q:"On what date did Atatürk land at Samsun?",a:["19 May 1919","23 April 1920","29 October 1923","30 August 1922"]}, tr:{q:"Atatürk hangi tarihte Samsun'a çıktı?",a:["19 Mayıs 1919","23 Nisan 1920","29 Ekim 1923","30 Ağustos 1922"]}, ex:{en:"Atatürk landed at Samsun on 19 May 1919, a date seen as the start of the War of Independence.",tr:"Atatürk, 19 Mayıs 1919'da Samsun'a çıktı; bu tarih Kurtuluş Savaşı'nın başlangıcı sayılır."} },
  { id:"his037", t:"history", d:3, c:0, en:{q:"Who founded the Ottoman state?",a:["Osman I","Orhan","Ertuğrul","Mehmed the Conqueror"]}, tr:{q:"Osmanlı Devleti'ni kim kurdu?",a:["Osman Bey","Orhan Bey","Ertuğrul Gazi","Fatih Sultan Mehmet"]}, ex:{en:"Osman I founded the small principality in the late 1200s that grew into the Ottoman Empire.",tr:"I. Osman, 1200'lerin sonlarında zamanla Osmanlı İmparatorluğu'na dönüşecek küçük beyliği kurdu."} },
  { id:"his038", t:"history", d:3, c:0, en:{q:"In which year did Christopher Columbus first sail across the Atlantic Ocean?",a:["1492","1392","1512","1620"]}, tr:{q:"Kristof Kolomb Atlas Okyanusu'nu ilk kez hangi yıl aştı?",a:["1492","1392","1512","1620"]}, ex:{en:"Columbus's ships crossed the Atlantic and sighted land in the Caribbean in October 1492.",tr:"Kolomb'un gemileri Atlas Okyanusu'nu geçerek 1492 Ekim'inde Karayipler'de karaya ulaştı."} },
  { id:"his039", t:"history", d:3, c:0, en:{q:"In which country was paper first made, about 2,000 years ago?",a:["China","Australia","Brazil","Greece"]}, tr:{q:"Kâğıt yaklaşık 2000 yıl önce ilk kez hangi ülkede yapıldı?",a:["Çin","Avustralya","Brezilya","Yunanistan"]}, ex:{en:"Papermaking began in China around 2,000 years ago, later spreading west along trade routes.",tr:"Kâğıt yapımı yaklaşık 2.000 yıl önce Çin'de başladı ve daha sonra ticaret yolları aracılığıyla batıya yayıldı."} },
  { id:"his040", t:"history", d:3, c:0, en:{q:"Who built the first printing press in Europe, in the 1400s?",a:["Johannes Gutenberg","Leonardo da Vinci","Galileo Galilei","Thomas Edison"]}, tr:{q:"1400'lü yıllarda Avrupa'da ilk matbaayı kim kurdu?",a:["Johannes Gutenberg","Leonardo da Vinci","Galileo Galilei","Thomas Edison"]}, ex:{en:"Johannes Gutenberg built Europe's first printing press with movable metal type around 1440.",tr:"Johannes Gutenberg, Avrupa'nın hareketli metal harflerle çalışan ilk matbaasını 1440 civarında yaptı."} },
  { id:"his041", t:"history", d:3, c:0, en:{q:"What was the picture writing of the ancient Egyptians called?",a:["Hieroglyphs","Runes","Cuneiform","Musical notes"]}, tr:{q:"Eski Mısırlıların resim yazısına ne ad verilir?",a:["Hiyeroglif","Runik yazı","Çivi yazısı","Nota işaretleri"]}, ex:{en:"Hieroglyphs were the picture-based writing system ancient Egyptians used on monuments and papyrus.",tr:"Hiyeroglifler, eski Mısırlıların anıtlarda ve papirüs üzerinde kullandığı resim tabanlı yazı sistemiydi."} },
  { id:"his042", t:"history", d:3, c:0, en:{q:"The ruins of the ancient city of Troy are found in which country today?",a:["Türkiye","Greece","Italy","Egypt"]}, tr:{q:"Antik Troya kentinin kalıntıları bugün hangi ülkededir?",a:["Türkiye","Yunanistan","İtalya","Mısır"]}, ex:{en:"The ruins believed to be ancient Troy sit in northwestern Türkiye, near the Dardanelles.",tr:"Antik Truva olduğuna inanılan kalıntılar, Kuzeybatı Türkiye'de Çanakkale Boğazı yakınında bulunur."} },
  { id:"his043", t:"history", d:3, c:0, en:{q:"Who made the first powered aeroplane flight, in 1903?",a:["The Wright brothers","The Montgolfier brothers","Louis Blériot","Amelia Earhart"]}, tr:{q:"1903'te motorlu ilk uçak uçuşunu kim gerçekleştirdi?",a:["Wright kardeşler","Montgolfier kardeşler","Louis Blériot","Amelia Earhart"]}, ex:{en:"Orville and Wilbur Wright achieved the first controlled, powered aeroplane flight in 1903.",tr:"Orville ve Wilbur Wright kardeşler, 1903'te ilk kontrollü ve motorlu uçak uçuşunu gerçekleştirdi."} },
  { id:"his044", t:"history", d:3, c:0, en:{q:"The ancient Hittites built their empire in which land?",a:["Anatolia","North Africa","Britain","India"]}, tr:{q:"Hititler imparatorluklarını hangi topraklarda kurdu?",a:["Anadolu","Kuzey Afrika","Britanya","Hindistan"]}, ex:{en:"The Hittites built a powerful empire centred in Anatolia, in what is now Türkiye, over 3,000 years ago.",tr:"Hititler, 3.000 yıldan fazla süre önce bugünkü Türkiye'nin bulunduğu Anadolu'da merkezli güçlü bir imparatorluk kurdu."} },
  { id:"his045", t:"history", d:3, c:0, en:{q:"Which Turkish national holiday is celebrated on 23 April?",a:["National Sovereignty and Children's Day","Republic Day","Victory Day","Youth and Sports Day"]}, tr:{q:"23 Nisan'da hangi ulusal bayram kutlanır?",a:["Ulusal Egemenlik ve Çocuk Bayramı","Cumhuriyet Bayramı","Zafer Bayramı","Gençlik ve Spor Bayramı"]}, ex:{en:"23 April celebrates both the opening of Türkiye's first parliament and the nation's children.",tr:"23 Nisan, hem Türkiye'nin ilk meclisinin açılışını hem de ülkenin çocuklarını kutlar."} },
  { id:"his046", t:"history", d:3, c:0, en:{q:"Julius Caesar was a famous leader of which ancient civilisation?",a:["Ancient Rome","Ancient Egypt","Ancient China","Ancient Persia"]}, tr:{q:"Jül Sezar hangi antik uygarlığın ünlü bir lideriydi?",a:["Antik Roma","Antik Mısır","Antik Çin","Antik Pers"]}, ex:{en:"Julius Caesar was a general and statesman who rose to power in ancient Rome before its empire began.",tr:"Julius Caesar, antik Roma'da imparatorluk başlamadan önce güce yükselen bir general ve devlet adamıydı."} },
  { id:"his047", t:"history", d:3, c:0, en:{q:"Who founded the Mongol Empire in the 1200s?",a:["Genghis Khan","Attila","Alexander the Great","Timur"]}, tr:{q:"1200'lü yıllarda Moğol İmparatorluğu'nu kim kurdu?",a:["Cengiz Han","Attila","Büyük İskender","Timur"]}, ex:{en:"Genghis Khan united the Mongol tribes in the early 1200s and built the largest land empire in history.",tr:"Cengiz Han, 1200'lerin başında Moğol kabilelerini birleştirerek tarihin en büyük kara imparatorluğunu kurdu."} },
  { id:"his048", t:"history", d:3, c:0, en:{q:"Which of these periods in history came first?",a:["The Stone Age","The Bronze Age","The Iron Age","The Middle Ages"]}, tr:{q:"Tarihte bu dönemlerden hangisi en önce gelir?",a:["Taş Devri","Tunç Devri","Demir Çağı","Orta Çağ"]}, ex:{en:"The Stone Age came first, followed later by the Bronze Age and then the Iron Age, named for the tools people used.",tr:"Taş Devri ilk sırada gelir, ardından insanların kullandığı araçlara göre adlandırılan Bronz Çağı ve Demir Çağı gelir."} },
  { id:"his049", t:"history", d:3, k:"tf", v:false, en:{q:"The First World War began in 1918."}, tr:{q:"Birinci Dünya Savaşı 1918 yılında başladı."}, ex:{en:"The First World War began in 1914 and lasted until 1918.",tr:"Birinci Dünya Savaşı 1914'te başladı ve 1918'e kadar sürdü."} },
  { id:"his050", t:"history", d:3, k:"tf", v:false, en:{q:"The pyramids of ancient Egypt were built as palaces for pharaohs to live in."}, tr:{q:"Eski Mısır'daki piramitler, firavunların yaşaması için saray olarak inşa edildi."}, ex:{en:"The pyramids were built as tombs to bury pharaohs and their treasures, not as homes to live in.",tr:"Piramitler, yaşamak için ev olarak değil, firavunları ve hazinelerini gömmek için mezar olarak inşa edildi."} },
  { id:"his051", t:"history", d:3, k:"tf", v:false, en:{q:"Marco Polo was a traveller from Spain who journeyed to China."}, tr:{q:"Marco Polo, Çin'e yolculuk yapan İspanyol bir gezgindi."}, ex:{en:"Marco Polo was a merchant and traveller from Venice, in what is now Italy, not Spain.",tr:"Marco Polo, İspanya'dan değil, bugünkü İtalya'da yer alan Venedik'ten gelen bir tüccar ve gezgindi."} },
  { id:"his052", t:"history", d:3, k:"tf", v:true, en:{q:"Anıtkabir, the great tomb of Atatürk, stands in Ankara."}, tr:{q:"Atatürk'ün büyük anıt mezarı Anıtkabir, Ankara'dadır."}, ex:{en:"Anıtkabir, Atatürk's monumental tomb, was built in Ankara and completed in 1953.",tr:"Atatürk'ün anıtsal mezarı olan Anıtkabir, Ankara'da inşa edildi ve 1953'te tamamlandı."} },
  { id:"his053", t:"history", d:4, c:0, en:{q:"In which year did the Titanic sink?",a:["1912","1905","1918","1921"]}, tr:{q:"Titanik hangi yıl battı?",a:["1912","1905","1918","1921"]}, ex:{en:"The Titanic sank on its first voyage in April 1912 after striking an iceberg.",tr:"Titanik, bir buzdağına çarptıktan sonra Nisan 1912'de ilk yolculuğunda battı."} },
  { id:"his054", t:"history", d:4, c:0, en:{q:"In which year did the Second World War end?",a:["1945","1944","1946","1943"]}, tr:{q:"İkinci Dünya Savaşı hangi yıl sona erdi?",a:["1945","1944","1946","1943"]}, ex:{en:"The Second World War ended in 1945 after Germany and then Japan surrendered.",tr:"İkinci Dünya Savaşı, önce Almanya'nın ardından Japonya'nın teslim olmasıyla 1945'te sona erdi."} },
  { id:"his055", t:"history", d:4, c:0, en:{q:"Which country gave the Statue of Liberty to the United States?",a:["France","Britain","Italy","The Netherlands"]}, tr:{q:"Özgürlük Heykeli'ni ABD'ye hangi ülke hediye etti?",a:["Fransa","İngiltere","İtalya","Hollanda"]}, ex:{en:"France gave the Statue of Liberty to the United States in 1886 as a gift of friendship.",tr:"Fransa, Özgürlük Heykeli'ni 1886'da dostluk hediyesi olarak Amerika Birleşik Devletleri'ne verdi."} },
  { id:"his056", t:"history", d:4, c:0, en:{q:"In which year was the Battle of Hastings fought in England?",a:["1066","1215","1120","950"]}, tr:{q:"İngiltere'deki Hastings Savaşı hangi yıl yapıldı?",a:["1066","1215","1120","950"]}, ex:{en:"William of Normandy defeated the English king at the Battle of Hastings in 1066.",tr:"Normandiyalı William, 1066'daki Hastings Savaşı'nda İngiliz kralını yendi."} },
  { id:"his057", t:"history", d:4, c:0, en:{q:"Who became the first emperor of Rome?",a:["Augustus","Nero","Constantine","Hannibal"]}, tr:{q:"Roma'nın ilk imparatoru kim oldu?",a:["Augustus","Neron","Konstantin","Hannibal"]}, ex:{en:"Augustus became Rome's first emperor in 27 BC, after the fall of the Roman Republic.",tr:"Augustus, Roma Cumhuriyeti'nin çöküşünün ardından MÖ 27'de Roma'nın ilk imparatoru oldu."} },
  { id:"his058", t:"history", d:4, c:0, en:{q:"Which civilisation built the mountain city of Machu Picchu?",a:["The Inca","The Aztecs","The Maya","The Vikings"]}, tr:{q:"Dağdaki Machu Picchu kentini hangi uygarlık kurdu?",a:["İnkalar","Aztekler","Mayalar","Vikingler"]}, ex:{en:"The Inca built Machu Picchu high in the Andes in the 1400s, likely as a royal retreat.",tr:"İnkalar, muhtemelen bir kraliyet dinlenme yeri olarak Machu Picchu'yu 1400'lerde And Dağları'nın yükseklerinde inşa etti."} },
  { id:"his059", t:"history", d:4, c:0, en:{q:"Which ancient civilisation ruled Anatolia from its capital Hattusa?",a:["The Hittites","The Lydians","The Phrygians","The Urartians"]}, tr:{q:"Başkenti Hattuşa olan hangi eski uygarlık Anadolu'da hüküm sürdü?",a:["Hititler","Lidyalılar","Frigler","Urartular"]}, ex:{en:"The Hittites ruled a large empire from their capital Hattusa, in what is now central Türkiye.",tr:"Hititler, bugünkü Orta Türkiye'de yer alan başkentleri Hattuşa'dan geniş bir imparatorluğu yönetti."} },
  { id:"his060", t:"history", d:4, c:0, en:{q:"Who introduced the printing press with movable type in Europe?",a:["Johannes Gutenberg","Leonardo da Vinci","Galileo Galilei","Marco Polo"]}, tr:{q:"Avrupa'da hareketli harfli matbaayı kim geliştirdi?",a:["Johannes Gutenberg","Leonardo da Vinci","Galileo Galilei","Marco Polo"]}, ex:{en:"Gutenberg's movable-type press let books be printed far faster than copying them by hand.",tr:"Gutenberg'in hareketli harfli matbaası, kitapların elle kopyalanmasından çok daha hızlı basılmasını sağladı."} },
  { id:"his061", t:"history", d:4, c:0, en:{q:"What was the ancient trade route linking China to the Mediterranean called?",a:["The Silk Road","The Amber Road","The Salt Route","The King's Highway"]}, tr:{q:"Çin'i Akdeniz'e bağlayan eski ticaret yolunun adı neydi?",a:["İpek Yolu","Kehribar Yolu","Tuz Yolu","Kral Yolu"]}, ex:{en:"The Silk Road was a network of trade routes carrying silk, spices and ideas between China and the Mediterranean.",tr:"İpek Yolu, Çin ile Akdeniz arasında ipek, baharat ve fikirleri taşıyan bir ticaret yolları ağıydı."} },
  { id:"his062", t:"history", d:4, c:0, en:{q:"In which year did the French Revolution begin with the storming of the Bastille?",a:["1789","1776","1804","1848"]}, tr:{q:"Bastille'in basılmasıyla başlayan Fransız İhtilali hangi yıl oldu?",a:["1789","1776","1804","1848"]}, ex:{en:"On 14 July 1789, Parisians stormed the Bastille prison, a spark that ignited the French Revolution.",tr:"14 Temmuz 1789'da Parisliler Bastille Hapishanesi'ni bastı; bu olay Fransız Devrimi'ni ateşleyen kıvılcım oldu."} },
  { id:"his063", t:"history", d:4, c:0, en:{q:"In which year did Türkiye adopt the Latin alphabet?",a:["1928","1923","1925","1934"]}, tr:{q:"Türkiye'de Harf Devrimi hangi yıl yapıldı?",a:["1928","1923","1925","1934"]}, ex:{en:"Türkiye replaced the Arabic script with the Latin alphabet as part of Atatürk's reforms in 1928.",tr:"Türkiye, Atatürk'ün reformları kapsamında 1928'de Arap alfabesini Latin alfabesiyle değiştirdi."} },
  { id:"his064", t:"history", d:4, c:0, en:{q:"Which Macedonian king conquered the Persian Empire?",a:["Alexander the Great","Hannibal","Pericles","Cyrus the Great"]}, tr:{q:"Pers İmparatorluğu'nu hangi Makedon kralı fethetti?",a:["Büyük İskender","Hannibal","Perikles","Büyük Kiros"]}, ex:{en:"Alexander the Great, king of Macedon, conquered the vast Persian Empire in the 300s BC.",tr:"Makedonya kralı Büyük İskender, MÖ 300'lü yıllarda geniş Pers İmparatorluğu'nu ele geçirdi."} },
  { id:"his065", t:"history", d:4, c:0, en:{q:"In which year did the Gallipoli (Çanakkale) battles take place?",a:["1915","1912","1918","1922"]}, tr:{q:"Çanakkale Savaşları hangi yıl yaşandı?",a:["1915","1912","1918","1922"]}, ex:{en:"The Gallipoli campaign was fought in 1915, when Ottoman forces defended the peninsula against Allied landings.",tr:"Çanakkale Savaşı 1915'te yaşandı; Osmanlı kuvvetleri yarımadayı İtilaf devletlerinin çıkarmalarına karşı savundu."} },
  { id:"his066", t:"history", d:4, k:"tf", v:false, en:{q:"The Hundred Years' War lasted exactly one hundred years."}, tr:{q:"Yüz Yıl Savaşları tam olarak yüz yıl sürmüştür."}, ex:{en:"The Hundred Years' War actually dragged on for 116 years, from 1337 to 1453.",tr:"Yüz Yıl Savaşları aslında 1337'den 1453'e kadar, tam 116 yıl sürdü."} },
  { id:"his067", t:"history", d:4, k:"tf", v:true, en:{q:"Howard Carter discovered the tomb of Tutankhamun in Egypt in 1922."}, tr:{q:"Howard Carter, Tutankamon'un mezarını 1922'de Mısır'da buldu."}, ex:{en:"Howard Carter found Tutankhamun's largely intact tomb in Egypt's Valley of the Kings in 1922.",tr:"Howard Carter, 1922'de Mısır'ın Krallar Vadisi'nde Tutankhamun'un büyük ölçüde bozulmamış mezarını buldu."} },
  { id:"his068", t:"history", d:4, k:"tf", v:false, en:{q:"The Hanging Gardens, one of the Seven Wonders of the ancient world, stood in the city of Athens."}, tr:{q:"Antik dünyanın yedi harikasından biri olan Asma Bahçeler, Atina kentinde bulunuyordu."}, ex:{en:"The Hanging Gardens are traditionally said to have stood in Babylon, not Athens.",tr:"Asma Bahçeler'in geleneksel olarak Atina'da değil, Babil'de bulunduğu söylenir."} },
  { id:"his069", t:"history", d:4, k:"tf", v:true, en:{q:"Hannibal took an army with war elephants across the Alps to attack Rome."}, tr:{q:"Hannibal, savaş filleriyle birlikte ordusunu Alpler'den geçirip Roma'ya saldırdı."}, ex:{en:"Hannibal, a Carthaginian general, famously marched his army and elephants across the Alps to invade Italy.",tr:"Kartacalı general Hannibal, İtalya'yı istila etmek için ordusunu ve fillerini Alpler'den geçirmesiyle ünlüdür."} },
  { id:"his070", t:"history", d:4, k:"tf", v:false, en:{q:"Vasco da Gama's expedition was the first to sail all the way around the world."}, tr:{q:"Dünyanın çevresini gemiyle ilk kez dolaşan sefer, Vasco da Gama'nın seferi oldu."}, ex:{en:"Vasco da Gama pioneered the sea route to India; the first full trip around the world was Magellan's expedition, finished by Elcano in 1522.",tr:"Vasco da Gama, Hindistan'a giden deniz yolunu açtı; dünyanın ilk kez tamamen dolaşılması ise Macellan'ın seferiyle, 1522'de Elcano tarafından tamamlandı."} },
  { id:"his071", t:"history", d:4, k:"tf", v:true, en:{q:"Ankara became the capital of Türkiye in 1923, taking over from Istanbul."}, tr:{q:"Ankara, 1923'te İstanbul'un yerine Türkiye'nin başkenti oldu."}, ex:{en:"Ankara replaced Istanbul as Türkiye's capital when the republic was declared in 1923.",tr:"Cumhuriyet 1923'te ilan edildiğinde Ankara, İstanbul'un yerine Türkiye'nin başkenti oldu."} },
  { id:"his072", t:"history", d:4, k:"tf", v:false, en:{q:"In the First World War the Ottoman Empire fought on the same side as Britain and France."}, tr:{q:"Birinci Dünya Savaşı'nda Osmanlı Devleti, İngiltere ve Fransa'nın yanında savaştı."}, ex:{en:"The Ottoman Empire joined the Central Powers, fighting against Britain and France in the First World War.",tr:"Osmanlı İmparatorluğu, Birinci Dünya Savaşı'nda İngiltere ve Fransa'ya karşı İttifak Devletleri'nin yanında savaştı."} },
  { id:"his073", t:"history", d:5, c:0, en:{q:"In which year did the Berlin Wall fall?",a:["1989","1991","1987","1990"]}, tr:{q:"Berlin Duvarı hangi yıl yıkıldı?",a:["1989","1991","1987","1990"]}, ex:{en:"The Berlin Wall, dividing East and West Berlin since 1961, was opened and torn down in 1989.",tr:"1961'den beri Doğu ve Batı Berlin'i ayıran Berlin Duvarı, 1989'da açılıp yıkıldı."} },
  { id:"his074", t:"history", d:5, c:0, en:{q:"Which architect designed the Selimiye Mosque in Edirne?",a:["Mimar Sinan","Sedefkâr Mehmed Ağa","Davud Ağa","Mimar Hayreddin"]}, tr:{q:"Edirne'deki Selimiye Camii'nin mimarı kimdir?",a:["Mimar Sinan","Sedefkâr Mehmed Ağa","Davud Ağa","Mimar Hayreddin"]}, ex:{en:"The great Ottoman architect Mimar Sinan designed the Selimiye Mosque, completed in Edirne in 1575.",tr:"Ünlü Osmanlı mimarı Mimar Sinan, 1575'te Edirne'de tamamlanan Selimiye Camii'ni tasarladı."} },
  { id:"his075", t:"history", d:5, c:0, en:{q:"In which year did the Chernobyl disaster happen?",a:["1986","1984","1989","1991"]}, tr:{q:"Çernobil felaketi hangi yıl yaşandı?",a:["1986","1984","1989","1991"]}, ex:{en:"A reactor explosion at the Chernobyl nuclear plant in Ukraine in 1986 caused a major radiation disaster.",tr:"1986'da Ukrayna'daki Çernobil nükleer santralindeki reaktör patlaması büyük bir radyasyon felaketine yol açtı."} },
  { id:"his076", t:"history", d:5, c:0, en:{q:"Who defeated Sultan Bayezid I at the Battle of Ankara in 1402?",a:["Timur","Genghis Khan","Hulagu Khan","Shah Ismail"]}, tr:{q:"1402 Ankara Savaşı'nda Yıldırım Bayezid'i kim yendi?",a:["Timur","Cengiz Han","Hülagü Han","Şah İsmail"]}, ex:{en:"Timur, the Central Asian conqueror, captured Sultan Bayezid I at the Battle of Ankara in 1402.",tr:"Orta Asyalı fatih Timur, 1402'deki Ankara Savaşı'nda Yıldırım Bayezid'i esir aldı."} },
  { id:"his077", t:"history", d:5, c:0, en:{q:"The Orkhon Inscriptions were left behind by which Turkic state?",a:["The Göktürks","The Ottomans","The Seljuks","The Huns"]}, tr:{q:"Orhun Yazıtları hangi Türk devletinden kalmıştır?",a:["Göktürkler","Osmanlılar","Selçuklular","Hunlar"]}, ex:{en:"The Göktürks carved the Orkhon Inscriptions in the early 700s, among the oldest known Turkic writings.",tr:"Göktürkler, bilinen en eski Türkçe yazıtlardan biri olan Orhun Yazıtları'nı 700'lerin başında oydurdu."} },
  { id:"his078", t:"history", d:5, c:0, en:{q:"Christopher Columbus's 1492 Atlantic voyage was paid for by which country?",a:["Spain","Portugal","England","France"]}, tr:{q:"Kristof Kolomb'un 1492 Atlantik seferini hangi ülke finanse etti?",a:["İspanya","Portekiz","İngiltere","Fransa"]}, ex:{en:"The Spanish crown financed Columbus's 1492 voyage after he sought funding across several courts.",tr:"Kolomb, birkaç saray dolaştıktan sonra 1492 seferini finanse eden İspanya Krallığı'nı buldu."} },
  { id:"his079", t:"history", d:5, c:0, en:{q:"Magna Carta of 1215 limited the power of which English king?",a:["King John","Henry VIII","Richard III","Edward I"]}, tr:{q:"1215 tarihli Magna Carta hangi İngiliz kralının yetkilerini sınırladı?",a:["Kral John","VIII. Henry","III. Richard","I. Edward"]}, ex:{en:"English barons forced King John to accept Magna Carta in 1215, limiting his royal power.",tr:"İngiliz baronları, Kral John'u 1215'te kraliyet gücünü sınırlayan Magna Carta'yı kabul etmeye zorladı."} },
  { id:"his080", t:"history", d:5, c:0, en:{q:"Whose improved steam engine helped power the Industrial Revolution?",a:["James Watt","Michael Faraday","Alessandro Volta","Louis Pasteur"]}, tr:{q:"Geliştirdiği buhar makinesiyle Sanayi Devrimi'ne güç veren kişi kimdir?",a:["James Watt","Michael Faraday","Alessandro Volta","Louis Pasteur"]}, ex:{en:"James Watt's more efficient steam engine design, from the 1770s, helped drive the Industrial Revolution.",tr:"James Watt'ın 1770'lerden itibaren geliştirdiği daha verimli buhar makinesi, Sanayi Devrimi'ni ilerletmeye yardımcı oldu."} },
  { id:"his081", t:"history", d:5, c:0, en:{q:"At which battle was Napoleon finally defeated in 1815?",a:["Waterloo","Trafalgar","Austerlitz","Borodino"]}, tr:{q:"Napolyon 1815'te hangi savaşta kesin yenilgiye uğradı?",a:["Waterloo","Trafalgar","Austerlitz","Borodino"]}, ex:{en:"Napoleon was decisively defeated by British and Prussian forces at Waterloo in 1815.",tr:"Napolyon, 1815'te İngiliz ve Prusya kuvvetleri tarafından Waterloo'da kesin olarak yenilgiye uğratıldı."} },
  { id:"his082", t:"history", d:5, c:0, en:{q:"Which ancient people of Mesopotamia developed cuneiform writing?",a:["The Sumerians","The Phoenicians","The Egyptians","The Aztecs"]}, tr:{q:"Mezopotamya'da çivi yazısını hangi kavim geliştirdi?",a:["Sümerler","Fenikeliler","Mısırlılar","Aztekler"]}, ex:{en:"The Sumerians of ancient Mesopotamia developed cuneiform, one of the earliest writing systems, using wedge-shaped marks.",tr:"Antik Mezopotamya'nın Sümerleri, kama şeklindeki işaretlerle en eski yazı sistemlerinden biri olan çivi yazısını geliştirdi."} },
  { id:"his083", t:"history", d:5, k:"tf", v:true, en:{q:"The Lydians, who lived in western Anatolia, were the first people known to mint coins."}, tr:{q:"Batı Anadolu'da yaşayan Lidyalılar, bilinen ilk madeni parayı basan halktır."}, ex:{en:"The Lydians of western Anatolia are credited with striking the first coins, around the 7th century BC.",tr:"Batı Anadolu'daki Lidyalılar, MÖ 7. yüzyıl civarında ilk madeni paraları basmalarıyla bilinir."} },
  { id:"his084", t:"history", d:5, k:"tf", v:false, en:{q:"The Renaissance began in France before spreading to the rest of Europe."}, tr:{q:"Rönesans, Avrupa'nın geri kalanına yayılmadan önce Fransa'da başlamıştır."}, ex:{en:"The Renaissance began in Italy in the 1300s and 1400s before spreading across the rest of Europe.",tr:"Rönesans, Avrupa'nın geri kalanına yayılmadan önce 1300'lü ve 1400'lü yıllarda İtalya'da başladı."} },
  { id:"his085", t:"history", d:5, k:"tf", v:true, en:{q:"Suleiman the Magnificent defeated the Hungarian army at the Battle of Mohács in 1526."}, tr:{q:"Kanuni Sultan Süleyman, 1526'daki Mohaç Savaşı'nda Macar ordusunu yendi."}, ex:{en:"Suleiman the Magnificent crushed the Hungarian army at Mohács in 1526, extending Ottoman power into central Europe.",tr:"Kanuni Sultan Süleyman, 1526'da Mohaç'ta Macar ordusunu ezerek Osmanlı gücünü orta Avrupa'ya genişletti."} },
  { id:"his086", t:"history", d:5, k:"tf", v:false, en:{q:"Democracy first developed in the ancient Greek city-state of Sparta."}, tr:{q:"Demokrasi ilk kez Antik Yunan şehir devleti Sparta'da ortaya çıkmıştır."}, ex:{en:"Democracy first developed in ancient Athens, not Sparta, which was instead ruled by a small military elite.",tr:"Demokrasi ilk olarak Sparta'da değil antik Atina'da gelişti; Sparta bunun yerine küçük bir askerî seçkinler tarafından yönetiliyordu."} },
  { id:"his087", t:"history", d:6, c:0, en:{q:"Which US president resigned from office in 1974?",a:["Richard Nixon","Gerald Ford","Lyndon B. Johnson","Jimmy Carter"]}, tr:{q:"1974'te görevinden istifa eden ABD başkanı kimdir?",a:["Richard Nixon","Gerald Ford","Lyndon B. Johnson","Jimmy Carter"]} },
  { id:"his088", t:"history", d:6, c:0, en:{q:"In which year was the Soviet Union formally dissolved?",a:["1991","1989","1990","1993"]}, tr:{q:"Sovyetler Birliği resmen hangi yıl dağıldı?",a:["1991","1989","1990","1993"]} },
  { id:"his089", t:"history", d:6, c:0, en:{q:"What was the first artificial satellite put into orbit?",a:["Sputnik 1","Explorer 1","Vostok 1","Telstar"]}, tr:{q:"Yörüngeye yerleştirilen ilk yapay uydu hangisidir?",a:["Sputnik 1","Explorer 1","Vostok 1","Telstar"]} },
  { id:"his090", t:"history", d:6, c:0, en:{q:"Which treaty signed in 1923 ended the Turkish War of Independence?",a:["The Treaty of Lausanne","The Treaty of Sèvres","The Armistice of Mudros","The Treaty of Moscow"]}, tr:{q:"1923'te imzalanan hangi antlaşma Kurtuluş Savaşı'nı sona erdirdi?",a:["Lozan Antlaşması","Sevr Antlaşması","Mondros Ateşkesi","Moskova Antlaşması"]} },
  { id:"his091", t:"history", d:6, c:0, en:{q:"Which philosopher was the tutor of Alexander the Great?",a:["Aristotle","Plato","Socrates","Pythagoras"]}, tr:{q:"Büyük İskender'in hocası olan filozof kimdir?",a:["Aristoteles","Platon","Sokrates","Pisagor"]} },
  { id:"his092", t:"history", d:6, c:0, en:{q:"Who developed the first smallpox vaccine, in 1796?",a:["Edward Jenner","Louis Pasteur","Robert Koch","Alexander Fleming"]}, tr:{q:"1796'da ilk çiçek aşısını geliştiren kişi kimdir?",a:["Edward Jenner","Louis Pasteur","Robert Koch","Alexander Fleming"]} },
  { id:"his093", t:"history", d:6, c:0, en:{q:"Which city was the Ottoman capital immediately before Istanbul?",a:["Edirne","Bursa","İznik","Konya"]}, tr:{q:"İstanbul'dan hemen önceki Osmanlı başkenti hangi şehirdi?",a:["Edirne","Bursa","İznik","Konya"]} },
  { id:"his094", t:"history", d:6, c:0, en:{q:"In which year did women in Türkiye gain the right to vote in national elections?",a:["1934","1930","1926","1945"]}, tr:{q:"Türkiye'de kadınlar genel seçimlerde oy hakkını hangi yıl kazandı?",a:["1934","1930","1926","1945"]} },
  { id:"his095", t:"history", d:6, c:0, en:{q:"In which year did the Cuban Missile Crisis take place?",a:["1962","1956","1959","1968"]}, tr:{q:"Küba Füze Krizi hangi yıl yaşandı?",a:["1962","1956","1959","1968"]} },
  { id:"his096", t:"history", d:6, c:0, en:{q:"Which Byzantine emperor had the Hagia Sophia built in the 6th century?",a:["Justinian I","Constantine I","Theodosius I","Heraclius"]}, tr:{q:"6. yüzyılda Ayasofya'yı yaptıran Bizans imparatoru kimdir?",a:["I. Justinianus","I. Constantinus","I. Theodosius","Herakleios"]} },
  { id:"his097", t:"history", d:6, c:0, en:{q:"In which year did India gain independence from British rule?",a:["1947","1935","1950","1962"]}, tr:{q:"Hindistan İngiliz yönetiminden hangi yıl bağımsızlığını kazandı?",a:["1947","1935","1950","1962"]} },
  { id:"his098", t:"history", d:6, c:0, en:{q:"Tenochtitlan was the capital of which civilisation?",a:["The Aztecs","The Incas","The Maya","The Olmecs"]}, tr:{q:"Tenochtitlan hangi uygarlığın başkentiydi?",a:["Aztekler","İnkalar","Mayalar","Olmekler"]} },
  { id:"his099", t:"history", d:6, k:"tf", v:true, en:{q:"Suleiman the Magnificent besieged Vienna in 1529 but failed to capture the city."}, tr:{q:"Kanuni Sultan Süleyman 1529'da Viyana'yı kuşattı ama şehri ele geçiremedi."} },
  { id:"his100", t:"history", d:6, k:"tf", v:false, en:{q:"The assassination that triggered the First World War took place in Belgrade in 1914."}, tr:{q:"Birinci Dünya Savaşı'nı tetikleyen suikast 1914'te Belgrad'da gerçekleşti."} },
  { id:"his101", t:"history", d:6, k:"tf", v:true, en:{q:"China's Terracotta Army was buried to guard the tomb of the first emperor, Qin Shi Huang."}, tr:{q:"Çin'deki Terracotta Ordusu, ilk imparator Qin Shi Huang'ın mezarını korumak için gömülmüştür."} },
  { id:"his102", t:"history", d:6, k:"tf", v:false, en:{q:"Nelson Mandela became president of South Africa in 1990."}, tr:{q:"Nelson Mandela 1990'da Güney Afrika devlet başkanı oldu."} },
  { id:"his103", t:"history", d:6, k:"tf", v:true, en:{q:"The Ottoman sultanate was abolished in 1922, before the republic was proclaimed in 1923."}, tr:{q:"Osmanlı saltanatı, 1923'te Cumhuriyet ilan edilmeden önce 1922'de kaldırıldı."} },
  { id:"his104", t:"history", d:6, k:"tf", v:false, en:{q:"Ferdinand Magellan himself completed the first voyage around the world and returned to Spain."}, tr:{q:"Macellan, dünyanın etrafını dolaşan ilk seferi bizzat tamamlayarak İspanya'ya döndü."} },
  { id:"his105", t:"history", d:7, c:0, en:{q:"Who was British Prime Minister when Britain declared war on Germany in 1939?",a:["Neville Chamberlain","Winston Churchill","Clement Attlee","Stanley Baldwin"]}, tr:{q:"1939'da İngiltere Almanya'ya savaş ilan ettiğinde başbakan kimdi?",a:["Neville Chamberlain","Winston Churchill","Clement Attlee","Stanley Baldwin"]} },
  { id:"his106", t:"history", d:7, c:0, en:{q:"In which year did euro banknotes and coins enter circulation?",a:["2002","1999","2000","2004"]}, tr:{q:"Euro banknot ve madeni paraları hangi yıl tedavüle girdi?",a:["2002","1999","2000","2004"]} },
  { id:"his107", t:"history", d:7, c:0, en:{q:"Which Ottoman sultan was deposed in 1909 after the 31 March Incident?",a:["Abdülhamid II","Mehmed V","Murad V","Abdülaziz"]}, tr:{q:"1909'da 31 Mart Olayı'nın ardından tahttan indirilen padişah kimdir?",a:["II. Abdülhamid","V. Mehmed Reşad","V. Murad","Abdülaziz"]} },
  { id:"his108", t:"history", d:7, c:0, en:{q:"Which Roman general lost three legions in the Teutoburg Forest in AD 9?",a:["Quinctilius Varus","Germanicus","Marcus Crassus","Agricola"]}, tr:{q:"MS 9'da Teutoburg Ormanı'nda üç Roma lejyonunu kaybeden komutan kimdir?",a:["Quinctilius Varus","Germanicus","Marcus Crassus","Agricola"]} },
  { id:"his109", t:"history", d:7, c:0, en:{q:"Who wrote the ten-volume Ottoman travel book known as the Seyahatname?",a:["Evliya Çelebi","Kâtip Çelebi","Piri Reis","Naima"]}, tr:{q:"Seyahatnâme adlı on ciltlik Osmanlı seyahat eserinin yazarı kimdir?",a:["Evliya Çelebi","Kâtip Çelebi","Piri Reis","Naima"]} },
  { id:"his110", t:"history", d:7, c:0, en:{q:"Which Inca ruler did Francisco Pizarro capture at Cajamarca in 1532?",a:["Atahualpa","Huayna Capac","Manco Cápac","Túpac Amaru"]}, tr:{q:"Francisco Pizarro'nun 1532'de Cajamarca'da esir aldığı İnka hükümdarı kimdir?",a:["Atahualpa","Huayna Capac","Manco Cápac","Túpac Amaru"]} },
  { id:"his111", t:"history", d:7, c:0, en:{q:"Which US president mediated the 1905 peace that ended the Russo-Japanese War?",a:["Theodore Roosevelt","Woodrow Wilson","William Howard Taft","Grover Cleveland"]}, tr:{q:"1905'te Rus-Japon Savaşı'nı bitiren barışa arabuluculuk eden ABD başkanı kimdir?",a:["Theodore Roosevelt","Woodrow Wilson","William Howard Taft","Grover Cleveland"]} },
  { id:"his112", t:"history", d:7, c:0, en:{q:"Which country's army defeated Italy at the Battle of Adwa in 1896?",a:["Ethiopia","Egypt","Morocco","Sudan"]}, tr:{q:"1896'daki Adwa Muharebesi'nde İtalyan ordusunu yenen ülke hangisidir?",a:["Etiyopya","Mısır","Fas","Sudan"]} },
  { id:"his113", t:"history", d:7, c:0, en:{q:"Which state did the Fourth Crusade set up in Constantinople in 1204?",a:["The Latin Empire","The Empire of Nicaea","The Empire of Trebizond","The Despotate of Epirus"]}, tr:{q:"Dördüncü Haçlı Seferi 1204'te Konstantinopolis'te hangi devleti kurdu?",a:["Latin İmparatorluğu","İznik İmparatorluğu","Trabzon İmparatorluğu","Epir Despotluğu"]} },
  { id:"his114", t:"history", d:7, c:0, en:{q:"Which admiral commanded China's seven treasure-fleet voyages from 1405 to 1433?",a:["Zheng He","Zhang Qian","Sima Qian","Kublai Khan"]}, tr:{q:"1405-1433 arasında Çin'in yedi hazine filosu seferine komuta eden amiral kimdir?",a:["Zheng He","Zhang Qian","Sima Qian","Kubilay Han"]} },
  { id:"his115", t:"history", d:7, k:"tf", v:true, en:{q:"Magellan died in the Philippines and Juan Sebastián Elcano completed the first voyage around the world."}, tr:{q:"Macellan Filipinler'de öldü; dünyanın çevresini dolaşan ilk yolculuğu Juan Sebastián Elcano tamamladı."} },
  { id:"his116", t:"history", d:7, k:"tf", v:false, en:{q:"In Türkiye the Caliphate was abolished in 1922, two years before the Sultanate."}, tr:{q:"Türkiye'de halifelik, saltanattan iki yıl önce, 1922'de kaldırılmıştır."} },
  { id:"his117", t:"history", d:7, k:"tf", v:false, en:{q:"Rome destroyed the city of Carthage in 146 BC, at the end of the Second Punic War."}, tr:{q:"Roma, Kartaca kentini MÖ 146'da İkinci Pön Savaşı'nın sonunda yıkmıştır."} },
  { id:"his118", t:"history", d:7, k:"tf", v:true, en:{q:"In 1538 an Ottoman fleet under Barbaros Hayreddin Pasha won the naval battle of Preveza."}, tr:{q:"1538'de Barbaros Hayreddin Paşa komutasındaki Osmanlı donanması Preveze Deniz Savaşı'nı kazandı."} },
  { id:"his119", t:"history", d:7, k:"tf", v:false, en:{q:"Mansa Musa, who made a famous pilgrimage to Mecca in 1324, ruled the Songhai Empire."}, tr:{q:"1324'te ünlü hac yolculuğunu yapan Mansa Musa, Songhay İmparatorluğu'nun hükümdarıydı."} },
  { id:"his120", t:"history", d:8, c:0, en:{q:"Which treaty ended the Thirty Years' War in 1648?",a:["The Peace of Westphalia","The Treaty of Utrecht","The Peace of Augsburg","The Treaty of Versailles"]}, tr:{q:"1648'de Otuz Yıl Savaşları'nı hangi antlaşma bitirdi?",a:["Vestfalya Barışı","Utrecht Antlaşması","Augsburg Barışı","Versay Antlaşması"]} },
  { id:"his121", t:"history", d:8, c:0, en:{q:"Which battle in 1071 opened Anatolia to Turkish settlement?",a:["Manzikert","Ankara","Kosovo","Mohács"]}, tr:{q:"1071'de Anadolu'nun kapılarını Türklere açan savaş hangisidir?",a:["Malazgirt","Ankara","Kosova","Mohaç"]} },
  { id:"his122", t:"history", d:8, c:0, en:{q:"After the Battle of Kadesh, Ramesses II signed a peace treaty with which Hittite king?",a:["Hattusili III","Muwatalli II","Suppiluliuma I","Tudhaliya IV"]}, tr:{q:"Kadeş Savaşı sonrası barış antlaşmasını II. Ramses hangi Hitit kralıyla imzaladı?",a:["III. Hattuşili","II. Muvatalli","I. Şuppiluliuma","IV. Tudhaliya"]} },
  { id:"his123", t:"history", d:8, c:0, en:{q:"Which battle in 636 ended Byzantine rule over Syria?",a:["Yarmouk","Qadisiyyah","Nahavand","Talas"]}, tr:{q:"636'da Suriye'deki Bizans egemenliğine hangi savaş son verdi?",a:["Yermük","Kadisiye","Nihavend","Talas"]} },
  { id:"his124", t:"history", d:8, c:0, en:{q:"Who wrote the Siyasetname, a book of government for Seljuk sultan Malik Shah?",a:["Nizam al-Mulk","Yusuf Khass Hajib","Mahmud of Kashgar","Al-Ghazali"]}, tr:{q:"Selçuklu sultanı Melikşah için Siyasetname adlı eseri kim yazdı?",a:["Nizamülmülk","Yusuf Has Hacib","Kaşgarlı Mahmud","Gazali"]} },
  { id:"his125", t:"history", d:8, c:0, en:{q:"In which year did the Acts of Union make England and Scotland one kingdom?",a:["1707","1603","1801","1649"]}, tr:{q:"İngiltere ile İskoçya, Birleşme Yasaları'yla hangi yıl tek bir krallık oldu?",a:["1707","1603","1801","1649"]} },
  { id:"his126", t:"history", d:8, c:0, en:{q:"Which Ethiopian emperor defeated an Italian army at Adwa in 1896?",a:["Menelik II","Haile Selassie","Tewodros II","Yohannes IV"]}, tr:{q:"1896'da Adova'da İtalyan ordusunu yenen Etiyopya imparatoru kimdir?",a:["II. Menelik","Haile Selassie","II. Tewodros","IV. Yohannes"]} },
  { id:"his127", t:"history", d:8, c:0, en:{q:"The 1839 Edict of Gülhane, which opened the Tanzimat era, was proclaimed under which sultan?",a:["Abdülmecid I","Mahmud II","Abdülaziz","Abdülhamid II"]}, tr:{q:"Tanzimat'ı başlatan 1839 Gülhane Hatt-ı Hümayunu hangi padişah döneminde ilan edildi?",a:["I. Abdülmecid","II. Mahmud","Abdülaziz","II. Abdülhamid"]} },
  { id:"his128", t:"history", d:8, c:0, en:{q:"Which ship laid the first lasting transatlantic telegraph cable in 1866?",a:["Great Eastern","Agamemnon","Niagara","Great Britain"]}, tr:{q:"İlk kalıcı transatlantik telgraf kablosunu 1866'da hangi gemi döşedi?",a:["Great Eastern","Agamemnon","Niagara","Great Britain"]} },
  { id:"his129", t:"history", d:8, c:0, en:{q:"Who was the first Secretary-General of the United Nations?",a:["Trygve Lie","Dag Hammarskjöld","U Thant","Kurt Waldheim"]}, tr:{q:"Birleşmiş Milletler'in ilk Genel Sekreteri kimdi?",a:["Trygve Lie","Dag Hammarskjöld","U Thant","Kurt Waldheim"]} },
  { id:"his130", t:"history", d:8, k:"tf", v:false, en:{q:"The 1774 Treaty of Küçük Kaynarca ended a war between the Ottoman Empire and Austria."}, tr:{q:"1774 Küçük Kaynarca Antlaşması, Osmanlı Devleti ile Avusturya arasındaki savaşı sona erdirdi."} },
  { id:"his131", t:"history", d:8, k:"tf", v:false, en:{q:"Hannibal crossed the Alps with his war elephants during the First Punic War."}, tr:{q:"Hannibal, savaş filleriyle Alpler'i Birinci Pön (Kartaca) Savaşı sırasında aşmıştır."} },
  { id:"his132", t:"history", d:8, k:"tf", v:false, en:{q:"Metternich, who presided over the Congress of Vienna in 1814-15, was Prussia's foreign minister."}, tr:{q:"1814-15 Viyana Kongresi'ne başkanlık eden Metternich, Prusya'nın dışişleri bakanıydı."} },
  { id:"his133", t:"history", d:8, k:"tf", v:true, en:{q:"In 1917 Germany's Zimmermann Telegram offered Mexico the return of Texas, New Mexico and Arizona."}, tr:{q:"Almanya, 1917 Zimmermann Telgrafı'nda Meksika'ya Teksas, New Mexico ve Arizona'yı geri kazanmayı önerdi."} }
);
